	/**
	 * Default Constructor
	 */
    public PaymentProcessorService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new PaymentProcessorEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(PaymentProcessorRepository.class) );
		this.validator		= applicationContext.getBean(PaymentProcessorValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		PaymentProcessor
	 */
		public PaymentProcessor createPaymentProcessor( CreatePaymentProcessorCommand command ) {

		PaymentProcessor entity = new PaymentProcessor();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setPaymentProcessorId( command.getPaymentProcessorId() );
            entity.setName( command.getName() );
            entity.setProcessorCode( command.getProcessorCode() );
            entity.setNetworkSupport( command.getNetworkSupport() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of PaymentProcessor {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdatePaymentProcessorCommand
	 * @return		PaymentProcessor
	 */
	public PaymentProcessor updatePaymentProcessor( UpdatePaymentProcessorCommand command ) {

		PaymentProcessor entity = new PaymentProcessor();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setPaymentProcessorId( command.getPaymentProcessorId() );
            entity.setName( command.getName() );
            entity.setProcessorCode( command.getProcessorCode() );
            entity.setNetworkSupport( command.getNetworkSupport() );
            entity.setInstitutions( command.getInstitutions() );
            entity.setContracts( command.getContracts() );
            entity.setSettlements( command.getSettlements() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of PaymentProcessor {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeletePaymentProcessorCommand
	 */
	public void delete( DeletePaymentProcessorCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getPaymentProcessorId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of PaymentProcessor {0} ", id );

	}

	/**
	 * Method to retrieve the PaymentProcessor via PaymentProcessorFetchOneSummary
	 * @param 	summary PaymentProcessorFetchOneSummary
	 * @return 	PaymentProcessorFetchOneResponse
	 */
	public PaymentProcessor getPaymentProcessor( PaymentProcessorFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "PaymentProcessorFetchOneSummary arg cannot be null" );

		PaymentProcessor entity = null;
		UUID id = summary.getPaymentProcessorId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a PaymentProcessor using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all PaymentProcessors
	 *
	 * @return 	List<PaymentProcessor>
	 */
    public List<PaymentProcessor> getAllPaymentProcessor() {
		List<PaymentProcessor> list = projector.findAll( new FindAllPaymentProcessorQuery() );
		return list;
	}


	/**
	 * add FinancialInstitution to Institutions
	 * @param		command AssignInstitutionsToPaymentProcessorCommand
	 */
	public void addToInstitutions( AssignInstitutionsToPaymentProcessorCommand command ) {

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.addToInstitutions(command.getPaymentProcessorId(), command.getAddTo());
	}

